part of 'component_editor_bloc.dart';

/// The status of the [ComponentEditorBloc].
enum ComponentEditorStatus() {
  /// The component can be edited.
  ready,

  /// The component is being saved.
  saving,

  /// The component was saved and its code generated.
  saved,

  /// The component was saved, but its code was not generated because a
  /// file that was not generated by the editor is in the way.
  codeConflict,

  /// The component can't be saved because some of its classes are
  /// generated for other components too; see
  /// [ComponentEditorState.conflictingClassNames] and
  /// [ComponentEditorState.rootClassOwner].
  classConflict,

  /// The component was saved, but generating its code failed.
  codeFailure,

  /// Something went wrong while saving.
  failure;

  /// Whether the component was saved, even if its code was not generated.
  bool get isSaved =>
      this == saved || this == codeConflict || this == codeFailure;
}

/// {@template component_editor_state}
/// The state of the [ComponentEditorBloc].
/// {@endtemplate}
final class const ComponentEditorState({
  /// The component being edited, including unsaved changes.
  required final Component component,

  /// The component as it was last saved.
  required final Component savedComponent,

  /// The current status.
  final ComponentEditorStatus status = ComponentEditorStatus.ready,

  /// The path of the selected node of the [component] tree, see
  /// [ComponentTree]. The root, the empty path, is selected by default.
  final List<int> selectedPath = const [],

  /// The classes generated for the other components of the project, which
  /// the children of [component] must not generate again (see
  /// [ComponentTree.generatedClassNames]), with the component that
  /// generates each one.
  final Map<String, Component> takenClassNames = const {},

  /// Whether the generated code doesn't match [savedComponent]: it was
  /// missing or outdated when the editor opened, or the last save didn't
  /// generate it (see [ComponentEditorStatus.codeConflict] and
  /// [ComponentEditorStatus.codeFailure]).
  ///
  /// The component can then be saved without changes, to generate the
  /// code once whatever was in the way is fixed.
  final bool isCodeOutdated = false,

  /// Whether the preview highlights the selected node, when it has a size
  /// or a radius (see [SizedComponent] and [RadiusComponent]).
  final bool isSelectionHighlighted = true,

  /// Whether the preview outlines the hitboxes ([HitboxComponent]), which
  /// draw nothing themselves.
  final bool areHitboxesVisible = true,

  /// The palette of the project, whose colors paints can use (see
  /// [ComponentPaint.paletteColor]).
  final Palette palette = const Palette(),

  /// The contents of the images the [component] draws, by asset path (see
  /// [ComponentSprite.image]). Images that can't be read are missing.
  final Map<String, Uint8List> spriteImages = const {},

  /// The zoom of the preview, `1` being the actual size.
  ///
  /// It is an editor preference, remembered for each component, not part
  /// of the [component].
  final double zoom = EditorPreferencesRepository.defaultZoom,
}) extends Equatable {
  /// {@macro component_editor_state}
  this;

  /// The zoom after zooming in (see [ZoomLevels.next]), or `null` if
  /// [zoom] is the largest one.
  double? get nextZoom => ZoomLevels.next(zoom);

  /// The zoom after zooming out (see [ZoomLevels.previous]), or `null` if
  /// [zoom] is the smallest one.
  double? get previousZoom => ZoomLevels.previous(zoom);

  /// Whether the component can be saved: it has changes or its code is
  /// outdated, and it is not being saved already.
  bool get canSave =>
      (hasChanges || isCodeOutdated) && status != ComponentEditorStatus.saving;

  /// The classes of [component] that are generated for other components
  /// too, with the component that generates each one; see
  /// [takenClassNames].
  Map<String, Component> get conflictingClassNames => {
    for (final className in component.generatedClassNames)
      if (takenClassNames.containsKey(className))
        className: takenClassNames[className]!,
  };

  /// The other component that generates the class of the root [component]
  /// too, if any.
  ///
  /// Renaming children here can't fix this clash, and components can't be
  /// renamed: a child of the other component must be renamed, or, if the
  /// clash is between the two roots, one of the components deleted.
  Component? get rootClassOwner =>
      takenClassNames[component.generatedClassName];

  /// The selected node of the [component] tree.
  Component get selectedNode => component.nodeAt(selectedPath);

  /// Whether the selected node is the root [component].
  bool get isRootSelected => selectedPath.isEmpty;

  /// Whether [component] has changes that were not saved yet.
  bool get hasChanges => component != savedComponent;

  /// Returns a copy of this state with the given fields replaced.
  ComponentEditorState copyWith({
    ComponentEditorStatus? status,
    Component? component,
    Component? savedComponent,
    List<int>? selectedPath,
    Map<String, Component>? takenClassNames,
    bool? isCodeOutdated,
    bool? isSelectionHighlighted,
    bool? areHitboxesVisible,
    Palette? palette,
    Map<String, Uint8List>? spriteImages,
    double? zoom,
  }) {
    return ComponentEditorState(
      status: status ?? this.status,
      component: component ?? this.component,
      savedComponent: savedComponent ?? this.savedComponent,
      selectedPath: selectedPath ?? this.selectedPath,
      takenClassNames: takenClassNames ?? this.takenClassNames,
      isCodeOutdated: isCodeOutdated ?? this.isCodeOutdated,
      isSelectionHighlighted:
          isSelectionHighlighted ?? this.isSelectionHighlighted,
      areHitboxesVisible: areHitboxesVisible ?? this.areHitboxesVisible,
      palette: palette ?? this.palette,
      spriteImages: spriteImages ?? this.spriteImages,
      zoom: zoom ?? this.zoom,
    );
  }

  @override
  List<Object> get props => [
    status,
    component,
    savedComponent,
    selectedPath,
    takenClassNames,
    isCodeOutdated,
    isSelectionHighlighted,
    areHitboxesVisible,
    palette,
    spriteImages,
    zoom,
  ];
}
